import { describeBarcodeBinding, describeBarcodeBound } from './barcode-binding.js';
import { createBindConsentChangeEvent, createMapBarcodeChangeEvent } from './health-events.js';

/**
 * Story 373 (pwa-nutrition-17) — the barcode-binding UI that `<food-log>` and
 * `<meal-ingredient-picker>` each carried a copy of.
 *
 * - `kind="offer"`: the code a dead-end scan left behind, its scope, and the opt-in to remember it
 *   for the next pick (stories 342, 344). Ticking it emits BIND_CONSENT_CHANGE.
 * - `kind="bound"`: the confirmation once a code is bound, with Change, which emits
 *   MAP_BARCODE_CHANGE for the code.
 *
 * State lives in attributes (`barcode`, `consent`, `food-name`), so a host can set them before
 * this element upgrades — its own connectedCallback runs first. It renders into light DOM, so the
 * parts keep their ids in the host's shadow root and take the host's `barcode-binding.css`.
 */
export class BarcodeBindingBanner extends HTMLElement {
    static get observedAttributes(): string[] {
        return ['barcode', 'consent', 'food-name'];
    }

    connectedCallback(): void {
        this.render();
    }

    attributeChangedCallback(): void {
        if (this.isConnected) this.render();
    }

    private get kind(): 'offer' | 'bound' {
        return this.getAttribute('kind') === 'bound' ? 'bound' : 'offer';
    }

    private ensureParts(): void {
        if (this.childElementCount > 0) return;
        if (this.kind === 'offer') {
            this.innerHTML = `
                <span class="map-banner-code" id="map-barcode-code"></span>
                <p class="map-banner-scope" id="map-barcode-scope"></p>
                <label class="map-banner-consent">
                    <input type="checkbox" id="map-barcode-consent">
                    <span>Remember this code for the food I pick below</span>
                </label>
            `;
            this.querySelector('#map-barcode-consent')!.addEventListener('change', (event) => {
                const consent = (event.target as HTMLInputElement).checked;
                this.toggleAttribute('consent', consent);
                this.dispatchEvent(createBindConsentChangeEvent({ consent }));
            });
        } else {
            this.innerHTML = `
                <span id="map-barcode-bound-text"></span>
                <button class="map-bound-change" id="map-barcode-change" type="button">Change</button>
            `;
            this.querySelector('#map-barcode-change')!.addEventListener('click', () => {
                const barcode = this.getAttribute('barcode');
                if (barcode) this.dispatchEvent(createMapBarcodeChangeEvent({ barcode }));
            });
        }
    }

    private render(): void {
        this.ensureParts();
        const barcode = this.getAttribute('barcode');
        this.hidden = !barcode;
        if (this.kind === 'offer') {
            this.querySelector('#map-barcode-code')!.textContent = barcode ?? '';
            this.querySelector('#map-barcode-scope')!.textContent = barcode ? describeBarcodeBinding(barcode).scope : '';
            (this.querySelector('#map-barcode-consent') as HTMLInputElement).checked = this.hasAttribute('consent');
        } else {
            this.querySelector('#map-barcode-bound-text')!.textContent =
                barcode ? describeBarcodeBound(barcode, this.getAttribute('food-name') ?? 'this food') : '';
        }
    }
}

if (!customElements.get('barcode-binding-banner')) {
    customElements.define('barcode-binding-banner', BarcodeBindingBanner);
}

function setBanner(banner: HTMLElement, barcode: string | null, extra: Record<string, string | boolean | null>): void {
    for (const [name, value] of Object.entries(extra)) {
        if (value === null || value === false) banner.removeAttribute(name);
        else banner.setAttribute(name, value === true ? '' : value);
    }
    if (barcode) banner.setAttribute('barcode', barcode);
    else banner.removeAttribute('barcode');
    banner.hidden = !barcode;
}

/**
 * The offer, plus the two things it changes on the host: the pick hint and the search
 * placeholder (story 344 — the screen only asks "which food is this?" once the next tap means it).
 */
export function showBindingOffer(root: ShadowRoot, barcode: string | null, consent: boolean, defaultPlaceholder: string): void {
    const banner = root.getElementById('map-barcode-banner');
    const hint = root.getElementById('pick-hint');
    const search = root.getElementById('search-input') as HTMLInputElement | null;
    if (!banner || !hint) return;
    setBanner(banner, barcode, { consent: Boolean(barcode) && consent });
    hint.hidden = !(barcode && consent);
    if (search) {
        search.placeholder = barcode && consent ? 'Search for the food this barcode means…' : defaultPlaceholder;
    }
}

/** The confirmation of a code just bound to `foodName`; null hides it. */
export function showBindingBound(root: ShadowRoot, barcode: string | null, foodName?: string): void {
    const bar = root.getElementById('map-barcode-bound');
    if (!bar) return;
    setBanner(bar, barcode, { 'food-name': barcode ? (foodName ?? 'this food') : null });
}
