import { offDefaultServing, offNutritionToFoodItem, uuidv7, type FoodItem, type NewFoodItem } from '@motivation/shared';
import type { OFFProduct } from '../services/openfoodfacts.service.js';
import { foodLineView, newFoodLineView, type LineView } from './line-view.js';

/** An Open Food Facts product as the food it becomes when it is logged or added (418 #7). */
export function offProductToNewFoodItem(product: OFFProduct): NewFoodItem {
    // The server-side OFF image adopter (story 125) reads image_url out of raw_json, so it
    // doesn't have to round-trip OFF a second time.
    const raw_json = product.image_url ? JSON.stringify({ image_url: product.image_url }) : undefined;
    return {
        canonical_name: product.product_name,
        display_name: product.product_name,
        brand: product.brands,
        barcode: product.barcode,
        source: 'openfoodfacts',
        source_ref: product.barcode,
        // Story 369: the server's branded fall-through maps a hit with these same two calls.
        default_serving_amount: offDefaultServing(product),
        ...offNutritionToFoodItem(product),
        raw_json,
    };
}

/** What a picked food starts at: its usual serving, else its serving, else one base (as the server did). */
export function defaultAmount(food: Pick<FoodItem, 'default_serving_amount' | 'serving_quantity' | 'base_amount'>): number {
    return food.default_serving_amount ?? food.serving_quantity ?? food.base_amount;
}

/** A picked library food or OFF product as a new line at its default amount. */
export function pickedLine(pick: { kind: 'food'; item: FoodItem } | { kind: 'off'; product: OFFProduct }): LineView {
    if (pick.kind === 'food') return foodLineView(pick.item, defaultAmount(pick.item), uuidv7());
    const food = offProductToNewFoodItem(pick.product);
    return { ...newFoodLineView(food, defaultAmount({ default_serving_amount: food.default_serving_amount ?? null, serving_quantity: null, base_amount: food.base_amount }), uuidv7()), badge: 'off' };
}
