import { LABEL_READ_FIELDS, type LabelReadField, type LabelReadResult, type NewFoodItem } from '@motivation/shared';
import { FilesService } from '../services/files.service.js';
import { HealthService, LabelReadError } from '../services/health.service.js';

/**
 * Story 338 — an unread macro named the way a label names it, not the way the
 * column does. "sodium_mg_per_base" is not a thing anyone reads off a package.
 */
const UNREAD_FIELD_LABELS: Record<LabelReadField, string> = {
    calories_per_base: 'energy',
    protein_g_per_base: 'protein',
    carbs_g_per_base: 'carbohydrate',
    fat_g_per_base: 'fat',
    fiber_g_per_base: 'fibre',
    sugar_g_per_base: 'sugars',
    sodium_mg_per_base: 'salt',
};

/** The unread fields as the label names them, in the order it prints them. */
export function unreadLabels(fields: LabelReadField[]): string[] {
    return [...fields]
        .sort((a, b) => LABEL_READ_FIELDS.indexOf(a) - LABEL_READ_FIELDS.indexOf(b))
        .map((f) => UNREAD_FIELD_LABELS[f] ?? f);
}

/** What a read that got nothing opens: an empty draft per 100 g, every macro unread. */
export function emptyLabelDraft(): LabelReadResult {
    return {
        draft: { canonical_name: '', display_name: '', source: 'label_photo', base_amount: 100, base_unit: 'g' },
        basis: 'per_100g',
        unread: [...LABEL_READ_FIELDS],
        confidence_score: 0,
        notes: '',
    };
}

/**
 * Story 338 — upload the photo and read it. The read runs on the server against the stored
 * bytes, so an upload that only queued (offline) has nothing to read and says so. A label the
 * model could not read is `problem`, with an empty draft to fill in by hand — another photo of
 * the same label will not do better; any other failure (GPU busy, offline, timeout) throws,
 * since retrying is the fix.
 */
export async function readLabelPhoto(file: File): Promise<{ result: LabelReadResult; problem: string | null }> {
    const upload = await FilesService.uploadImageOrQueue('ai', file, file.name || 'label.jpg');
    if (upload.status !== 'uploaded') {
        throw new Error('Your photo is queued for upload (offline or server unreachable). Reading a label needs the server — try again once it has uploaded.');
    }
    try {
        return { result: await HealthService.readNutritionLabel(upload.image_path), problem: null };
    } catch (err) {
        if (err instanceof LabelReadError && err.reason === 'unreadable') return { result: emptyLabelDraft(), problem: err.message };
        throw err;
    }
}

/**
 * Story 353 — the label read fills in a match that had no energy value. The read's nutrition
 * goes onto the matched food; the name it was scanned under beats one read off a nutrition
 * table, which rarely prints it, and its barcode stays its own.
 */
export function fillFromLabel(match: NewFoodItem, read: NewFoodItem): NewFoodItem {
    return {
        ...match,
        // The numbers are the label's now, and the row says where they came from.
        source: read.source,
        base_amount: read.base_amount,
        base_unit: read.base_unit,
        serving_label: read.serving_label ?? match.serving_label,
        serving_quantity: read.serving_quantity ?? match.serving_quantity,
        default_serving_amount: read.default_serving_amount ?? match.default_serving_amount,
        calories_per_base: read.calories_per_base,
        protein_g_per_base: read.protein_g_per_base,
        carbs_g_per_base: read.carbs_g_per_base,
        fat_g_per_base: read.fat_g_per_base,
        fiber_g_per_base: read.fiber_g_per_base,
        sugar_g_per_base: read.sugar_g_per_base,
        sodium_mg_per_base: read.sodium_mg_per_base,
        display_name: match.display_name || read.display_name,
        canonical_name: match.canonical_name || read.canonical_name,
        brand: match.brand ?? read.brand,
    };
}
