import stylesText from './line-add-dialog.css?inline';
import { uuidv7, type LabelReadResult, type NewFoodItem } from '@motivation/shared';
import { cssStyleSheet } from '../../../../utils/css.js';
import { showModalFresh } from '../../../../utils/dialog.js';
import { defaultAmount, pickedLine } from '../../../../utils/pick-line.js';
import { ingredientView, newFoodLineView, type LineView } from '../../../../utils/line-view.js';
import { readLabelPhoto, unreadLabels } from '../../../../utils/label-read.js';
import { HealthService } from '../../../../services/health.service.js';
import { createComponentLogger } from '../../../../utils/component-logger.js';
import { HEALTH_EVENTS, createLinePickedEvent, type FoodEditorSaveEvent, type FoodPickActionEvent, type FoodPickEvent } from '../../health-events.js';
import '../food-picker/food-picker.component.js';
import '../food-editor/food-editor.component.js';
import type { FoodPicker } from '../food-picker/food-picker.component.js';
import type { FoodEditor } from '../food-editor/food-editor.component.js';

const styles = cssStyleSheet(stylesText);
const log = createComponentLogger('line-add-dialog');

const template = document.createElement('template');
template.innerHTML = `
    <dialog class="sheet" aria-label="Add food">
        <div class="head">
            <span class="title">Add food</span>
            <button type="button" class="close" aria-label="Close">×</button>
        </div>
        <p class="status" role="status" hidden></p>
        <div class="label-host" hidden></div>
    </dialog>
`;

/**
 * Story 422 — "+ Add food" on a list of lines: `<food-picker>` in a sheet, over the editor it adds
 * to, so the edits made so far stay where they are. Story 434: the same picker as the Add-to
 * screen — search, Scan, Label, saved meals, Frequent. A food or Open Food Facts product comes out
 * as one `health:line-picked` at its usual amount; a meal as one per ingredient; a label read as
 * the drafted food, checked in the sheet first. Estimate is the Add-to screen's: it makes a whole
 * log, not a line. The picker is made on the first open: it fetches the frequent foods as it
 * connects, and an editor that never adds anything should not.
 */
export class LineAddDialog extends HTMLElement {
    private picker: FoodPicker | null = null;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        shadow.querySelector('.close')!.addEventListener('click', () => this.dialog.close());
        // A closed sheet keeps its picker: stop a scan it left open, forget a miss and a label draft.
        this.dialog.addEventListener('close', () => {
            this.picker?.closeScan();
            this.picker?.showMiss(null);
            this.showPicker();
        });
    }

    /** Open on the slot's frequent foods (recent foods with no slot). */
    open(mealType: string | null): void {
        const picker = this.picker ?? this.makePicker();
        if (mealType) picker.setAttribute('meal-type', mealType);
        else picker.removeAttribute('meal-type');
        this.showPicker();
        showModalFresh(this.dialog);
        picker.focusSearch();
    }

    private makePicker(): FoodPicker {
        const picker = document.createElement('food-picker') as FoodPicker;
        // Story 432: Scan is the picker's own, so the sheet scans without leaving the editor.
        picker.setAttribute('actions', 'scan label');
        picker.setAttribute('meals', '');
        picker.addEventListener(HEALTH_EVENTS.FOOD_PICK, (e: FoodPickEvent) => {
            e.stopPropagation();
            const { entry, bind } = e.detail;
            if (entry.kind === 'meal') {
                void this.pickMeal(entry.meal.id);
                return;
            }
            this.pick([pickedLine(entry.kind === 'food' ? { kind: 'food', item: entry.item } : { kind: 'off', product: entry.product })], bind ?? null);
        });
        picker.addEventListener(HEALTH_EVENTS.FOOD_PICK_ACTION, (e: FoodPickActionEvent) => {
            e.stopPropagation();
            if (e.detail.action === 'label') this.pickLabelPhoto();
        });
        this.dialog.append(picker);
        this.picker = picker;
        return picker;
    }

    private pick(lines: LineView[], bind: string | null): void {
        this.dialog.close();
        for (const line of lines) this.dispatchEvent(createLinePickedEvent({ line, bind }));
    }

    /** A saved meal's ingredients join as lines of their own. */
    private async pickMeal(id: string): Promise<void> {
        this.status('Opening the meal…');
        try {
            const meal = await HealthService.getMeal(id);
            this.status(null);
            this.pick(meal.ingredients.map((ingredient) => ({ ...ingredientView(ingredient), key: uuidv7() })), null);
        } catch (err) {
            log.warn('opening a picked meal failed', { id, error: String(err) });
            this.status(err instanceof Error ? err.message : String(err), true);
        }
    }

    /** Ask for the photo inside the tap that asked for it — a picker opened later is blocked. */
    private pickLabelPhoto(): void {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'image/*';
        input.setAttribute('capture', 'environment');
        input.addEventListener('change', () => {
            const file = input.files?.[0];
            if (file) void this.readLabel(file);
        });
        input.click();
    }

    private async readLabel(file: File): Promise<void> {
        this.status('Reading the label…');
        let read: { result: LabelReadResult; problem: string | null };
        try {
            read = await readLabelPhoto(file);
        } catch (err) {
            // The photo is fine and retrying is the fix: the picker stays where it was.
            log.warn('label read failed', { error: String(err) });
            this.status(err instanceof Error ? err.message : String(err), true);
            return;
        }
        this.status(read.problem ? `Could not read this label — fill it in by hand. ${read.problem}` : null, Boolean(read.problem));
        const editor = document.createElement('food-editor') as FoodEditor;
        editor.setAttribute('mode', 'label-draft');
        customElements.upgrade(editor);
        editor.food = read.result.draft;
        editor.unread = read.problem ? [] : unreadLabels(read.result.unread);
        editor.addEventListener(HEALTH_EVENTS.FOOD_EDITOR_SAVE, (e: FoodEditorSaveEvent) => {
            e.stopPropagation();
            const food: NewFoodItem = e.detail.food;
            const amount = defaultAmount({ default_serving_amount: food.default_serving_amount ?? null, serving_quantity: food.serving_quantity ?? null, base_amount: food.base_amount });
            // The food is created when the list it joins is saved.
            this.pick([{ ...newFoodLineView(food, amount, uuidv7()), badge: 'label' }], this.picker?.pendingBind ?? null);
        });
        const host = this.shadowRoot!.querySelector('.label-host') as HTMLElement;
        host.replaceChildren(editor);
        host.hidden = false;
        if (this.picker) this.picker.hidden = true;
    }

    private showPicker(): void {
        const host = this.shadowRoot!.querySelector('.label-host') as HTMLElement;
        host.replaceChildren();
        host.hidden = true;
        if (this.picker) this.picker.hidden = false;
        this.status(null);
    }

    private status(text: string | null, alert = false): void {
        const p = this.shadowRoot!.querySelector('.status') as HTMLElement;
        p.hidden = text === null;
        p.textContent = text ?? '';
        p.setAttribute('role', alert ? 'alert' : 'status');
        p.classList.toggle('alert', alert);
    }

    private get dialog(): HTMLDialogElement {
        return this.shadowRoot!.querySelector('dialog') as HTMLDialogElement;
    }
}

if (!customElements.get('line-add-dialog')) {
    customElements.define('line-add-dialog', LineAddDialog);
}
